# owner: platform
"""Absence notices for parents, built from attendance."""

from typing import List
from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed
from datetime import date

def _long_date(when: date) -> str:
    return f"{when:%B} {when.day}, {when.year}"

def _join_phrases(phrases: List[str]) -> str:
    """Join with commas and a final 'and'."""
    if len(phrases) <= 2:
        return " and ".join(phrases)
    head = ", ".join(phrases[:-1])
    return f"{head}, and {phrases[-1]}"

def _day_count(count: int) -> str:
    noun = "day" if count == 1 else "days"
    return f"{count} {noun}"

def _require_own_marks(
    student: Student, marks: List[Mark]
) -> None:
    """Refuse marks recorded for some other student."""
    for mark in marks:
        other = mark.student_id
        if other != student.student_id:
            raise ValueError(f"stray mark for {other}")

def _require_absences(
    student: Student, dates: List[date]
) -> None:
    if not dates:
        name = student.display_name
        raise ValueError(f"no absences for {name}")

def _notice_text(
    student: Student, dates: List[date]
) -> str:
    phrases = [_long_date(when) for when in dates]
    listed = _join_phrases(phrases)
    name = f"{student.first_name} {student.last_name}"
    count = _day_count(len(dates))
    return f"{name} was absent on {count}: {listed}."

# ---
def absence_notice(
    student: Student, marks: List[Mark]
) -> str:
    """Parent-facing absence notice. Raises ValueError."""
    _require_own_marks(student, marks)
    dates = sorted(set(days_missed(marks)))
    _require_absences(student, dates)
    return _notice_text(student, dates)
